-- 角色 = code 关联（不用 id，避免依赖自增顺序）
INSERT INTO sys_user_role (user_id, role_id, created_at)
SELECT u.id, r.id, NOW() FROM sys_user u JOIN sys_role r ON r.code = 'SUPER_ADMIN'
WHERE u.username IN ('lin.gong', 'emp001');
INSERT INTO sys_user_role (user_id, role_id, created_at)
SELECT u.id, r.id, NOW() FROM sys_user u JOIN sys_role r ON r.code = 'KB_ADMIN'
WHERE u.username = 'zhang.wei' OR (u.username LIKE 'emp%' AND CAST(SUBSTRING(u.username, 4) AS UNSIGNED) BETWEEN 2 AND 12);
INSERT INTO sys_user_role (user_id, role_id, created_at)
SELECT u.id, r.id, NOW() FROM sys_user u JOIN sys_role r ON r.code = 'AUDITOR'
WHERE u.username = 'liu.qiang' OR (u.username LIKE 'emp%' AND CAST(SUBSTRING(u.username, 4) AS UNSIGNED) BETWEEN 13 AND 15);
INSERT INTO sys_user_role (user_id, role_id, created_at)
SELECT u.id, r.id, NOW() FROM sys_user u JOIN sys_role r ON r.code = 'USER'
WHERE u.username IN ('li.na', 'wang.fang', 'chen.jing', 'zhou.min')
   OR (u.username LIKE 'emp%' AND CAST(SUBSTRING(u.username, 4) AS UNSIGNED) >= 16);
